<?php
if(PHP_SAPI!=='cli'||getenv('DB_DATABASE')!=='study_qa_monitor_sso039'){exit(2);}$_SERVER['argv']=array('index.php','cli/migrate');ob_start();require dirname(__DIR__).'/index.php';ob_end_clean();$ci =& get_instance();$ci->load->model(array('Review_model','Account_model'));$db=$ci->db;$db->db_debug=FALSE;$m=$ci->Review_model;
function rcheck($ok,$label){if(!$ok){throw new RuntimeException($label);}}
$u=$db->like('username','qa063_','after')->order_by('id','DESC')->get('st_users')->row_array();$user=$ci->Account_model->find_active_user($u['id']);$root=$ci->Account_model->find_active_user(1);$child=$ci->Account_model->find_active_user(3);
rcheck($db->where('is_demo',1)->count_all_results('st_reviews')===1000,'1000 simulation reviews');rcheck($db->where('is_demo',1)->where('rating',5)->count_all_results('st_reviews')===900,'90 percent 5 stars');rcheck($m->listing('published',1)['total']===0,'Simulation excluded publicly');
$v=array('display_name'=>'QA pengulas','body'=>"Pengalaman belum sesuai harapan. <script>alert('x')</script>",'rating'=>'1','revision'=>'0','consent'=>'1');rcheck($m->save($child,$v)['code']===403,'Child cannot publish review');$stale=$user;$stale['auth_stamp']='stale';rcheck($m->save($stale,$v)['code']===403,'Stale credentials rejected');rcheck($m->save($user,array_replace($v,array('rating'=>'0')))['code']===400,'Invalid rating rejected');rcheck($m->save($user,array_replace($v,array('consent'=>'0')))['code']===400,'Public consent required');
rcheck($m->save($user,$v)['ok'],'Save one-star review');$r=$m->own($user['id']);rcheck($r['status']==='pending','Pending moderation');rcheck($m->save($user,$v)['code']===409,'Duplicate revision rejected');rcheck($db->where('user_id',$user['id'])->count_all_results('st_reviews')===1,'One review per account');rcheck($m->listing('published',1)['total']===0,'Pending hidden');
rcheck($m->moderate($user,(string)$r['id'],(string)$r['revision'],'published','Pengalaman sah')['code']===403,'Admin-only moderation');rcheck($m->moderate($root,(string)$r['id'],(string)$r['revision'],'published','Pengalaman sah')['ok'],'Publish low-star allowed');$list=$m->listing('published',1);rcheck($list['total']===1 && (float)$list['summary']['average']===1.0,'Real-only aggregate');
$landing=$m->landing_sample(3);rcheck(count($landing['rows'])===1 && (int)$landing['rows'][0]['id']===(int)$r['id'],'Landing uses published real review');rcheck((int)$landing['summary']['total']===1 && (float)$landing['summary']['average']===1.0,'Landing summary excludes demo reviews');
$r=$m->own($user['id']);$v['revision']=(string)$r['revision'];rcheck($m->save($user,$v)['ok'],'Edit review');rcheck($m->listing('published',1)['total']===0,'Edits require remoderation');$r=$m->own($user['id']);
rcheck($db->query("CREATE TRIGGER qa066_fail_review BEFORE INSERT ON st_audit_events FOR EACH ROW BEGIN IF NEW.event_type='review.moderated' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='QA066 fault'; END IF; END"),'QA fault');try{rcheck(!$m->moderate($root,(string)$r['id'],(string)$r['revision'],'published','Pengalaman sah')['ok'],'Audit failure rejected');rcheck($m->own($user['id'])===$r,'Moderation rolled back');}finally{$db->query('DROP TRIGGER qa066_fail_review');}
echo "PASS 066: 1000 clearly isolated demo rows/900 five-star, zero demo public aggregate, actual one-star accepted, consent/account/child/auth guards, one-per-user/revision, moderation permissions, re-review after edit, audit rollback.\n";
